  "recipeIngredient": [
    "8 ounces (225g) guanciale (cured pork jowl), in one piece",
    "1 tablespoon (15ml) extra-virgin olive oil",
    "Kosher salt and freshly ground black pepper",
    "12 ounces (340g) rigatoni",
    "2 ounces (60g) finely grated Pecorino Romano cheese, plus more for serving"
  ],
  "recipeInstructions": [
    {
      "@type": "HowToStep",
      "position": 1,
      "name": null,
      "text": "Freeze guanciale for at least 15 minutes, and up to 45 minutes (partially freezing the guanciale makes it easier to slice). Using a sharp chef's knife, cut into 1/4-inch-thick planks, then cut planks into 1/4-inch-thick batons (lardons).",
      "image": "https://www.seriouseats.com/thmb/ayFg_V7k_GgNoF0DSVK50AhzZl0=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/__opt__aboutcom__coeus__resources__content_migration__serious_eats__seriouseats.com__2018__10__20181017-pasta-gricia-vicky-wasik-guanciale-1500x1125-e219bc1764dd4033b5426e02a2a61a2e.jpg",
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 2,
      "name": null,
      "text": "In a large 12-inch stainless steel skillet, heat oil over medium-low heat until shimmering. Add guanciale and cook, stirring occasionally, until fat has rendered and guanciale is golden brown and crisp, about 15 minutes. Using a slotted spoon, transfer guanciale to a plate; set aside. Reduce heat to low, and bloom about 1 teaspoon freshly ground black pepper in rendered guanciale fat until pepper foams and is aromatic, about 1 minute. Remove skillet from heat.",
      "image": "https://www.seriouseats.com/thmb/yKTBU8e-Yb-NCXp71L_fBpzKQFA=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/__opt__aboutcom__coeus__resources__content_migration__serious_eats__seriouseats.com__2018__10__20181017-pasta-gricia-vicky-wasik-pepper-1500x1125-a0131bbb7eee44519d96ea316fbaba5c.jpg",
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 3,
      "name": null,
      "text": "Meanwhile, in a Dutch oven or medium pot, bring 3 quarts of water and 2 teaspoons kosher salt to a boil over high heat. Set a colander inside a large heatproof bowl in the sink. Add rigatoni to water and cook, stirring frequently during the first minute to prevent pasta from sticking.",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 4,
      "name": null,
      "text": "Once pasta has cooked for 4 minutes 30 seconds, transfer 2 cups (475ml) of starchy pasta water to skillet. Return skillet to high heat and bring to a boil, swirling to emulsify pasta water with guanciale fat.",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 5,
      "name": null,
      "text": "When pasta has cooked for a total of 5 minutes, drain in prepared colander, then transfer pasta to skillet (the pasta will be very undercooked at this point, but it will continue cooking in the skillet); reserve drained pasta water.",
      "image": null,
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 6,
      "name": null,
      "text": "Cook rigatoni, swirling skillet constantly and gently stirring with a spoon or rubber spatula, to ensure even cooking and that the sauce remains emulsified, until pasta is al dente and sauce is thickened and reduced, 6 to 8 minutes; if sauce reduces too much before pasta has finished cooking, add more reserved pasta water to skillet in 1/4-cup increments. Add guanciale to skillet and carefully toss to combine.",
      "image": "https://www.seriouseats.com/thmb/E_lHhHs6LxkcqzULTHYqMhsAE3I=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/__opt__aboutcom__coeus__resources__content_migration__serious_eats__seriouseats.com__2018__10__20181017-pasta-gricia-vicky-wasik-adding-pasta-and-guanciale-1500x1125-8950b253083e4995823e3ec3aa82bc51.jpg",
      "imageCredit": null
    },
    {
      "@type": "HowToStep",
      "position": 7,
      "name": null,
      "text": "Remove from heat, add half of the grated Pecorino Romano, and toss or stir rapidly to combine. Once cheese is fully emulsified in the sauce, add remaining Pecorino Romano, and toss or stir rapidly once more to combine. Adjust sauce consistency as needed with more pasta water. Season with salt and pepper, if needed. Serve right away, passing more cheese at the table.",
      "image": "https://www.seriouseats.com/thmb/ZG9deGV9y7ScbFmGaAJQkfwo02A=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/__opt__aboutcom__coeus__resources__content_migration__serious_eats__seriouseats.com__2018__10__20181017-pasta-gricia-vicky-wasik-finishing-sauce-1500x1125-1c5955079a3b4a3c974cf6c5787b9004.jpg",
